out['items'].append(dict(id='author-ege-reading-links',exam='ege',block='reading',type='match',title='A quieter school · смысловые связи',text='Our school used to have a noisy corridor beside the library. A group of pupils asked whether anything could be done, A ___. Before suggesting a solution, they spent a week observing how the space was used. They discovered that most noise came from students waiting for clubs, B ___.\n\nThe pupils proposed moving the waiting area to an empty classroom. However, the room was already used for music lessons, C ___. The caretaker suggested a small entrance hall instead. It was bright and easy to reach, D ___.\n\nThe group added chairs and a noticeboard with club timetables. They asked users to speak quietly and keep the entrance clear. After a month they collected comments, E ___. Most students welcomed the change. The library became calmer, F ___. The group learned that a small improvement could begin with a careful question.',options=['so their first plan had to change','which showed that the new arrangement was useful','because several activities started at the same time','although they did not expect an immediate answer','and readers could concentrate more easily','whose instruments were all extremely expensive','so people would not have to wait in the corridor'],key='431725',max=2,number=11,why='A — уступка although (4); B — причина because (3); C — следствие занятости помещения (1); D — решение проблемы ожидания (7); E — which относится к comments (2); F — результат для читателей (5). Вариант 6 лишний.',source=source('ege'),shortened=True))
out['items'].append(dict(id='fipi-oge-audio-6',exam='oge',block='listening',type='gaps',title='Interview · № 6–11',context='В полной официальной записи найдите интервью задания 6–11. Впишите одно слово без артикля из записи; числа записывайте буквами.',audio='assets/audio/fipi-oge-written.mp3',source=source('oge',True),questions=[dict(label=str(6+i),text=t+' ___',base='',answers=a.split('|'),why='Ключ официальной демоверсии: '+a.replace('|',' / ')) for i,(t,a) in enumerate([('Current job','librarian'),('Number of jobs he/she has done','twelve'),('The foreign language he/she speaks','Chinese'),('Hobby','travelling|traveling'),('The musical instrument he/she plays','piano'),('Regular sports activity','jogging')])]))

# Speaking: official source read-alouds and interviews + distinct authored sets.
def speak(id,exam,task,title,text,prep,seconds,parts=None,official=False,images=None):
    out['speaking'].append(dict(id=id,exam=exam,task=task,title=title,text=text,prep=prep,seconds=seconds,parts=parts or [],source=source(exam,official),rubric=f'{exam}-speaking-{task}',images=images or []))
oge_read='Bicycles or bikes are an important means of transportation in many parts of the world. The first bicycles turned up in Europe in the first half of the 19th century but the word “bicycle” only appeared later, in 1868. There are more bicycles in the world than cars. A lot of people have realized that cycling is an easy way to get around and a great way to cut down on pollution. More and more cities have special places where people can borrow a bike and ride around the city. Over the past few years, a bicycle infrastructure has been created in Moscow. Cycling in the centre of Moscow in summer is one of the most pleasant and quickest ways of seeing the city.'
ege_read='Land pollution has its effect on people, animals and plants. That is why it is very important to stop land pollution as quickly as possible. Fortunately, there are several possible solutions to the land pollution problem, including conservation. For instance, we can leave old trees in a forest to naturally die instead of cutting them down. We must also process waste and dispose of it in the safest manner possible not to create huge landfills with tons of plastic. We should stop using so much plastic. Even if you stop buying plastic shopping bags each time you go shopping for food, and get a cloth bag instead, this simple step will make a difference. Instead of throwing something away, think about a way to reuse or recycle it. You can turn to organic gardening practices as well and stop using dangerous chemicals in your garden. Fighting land pollution needs everyone’s effort.'
for exam,text in [('oge',oge_read),('ege',ege_read)]: speak('fipi-'+exam+'-read',exam,1,'Чтение вслух · демоверсия',text,90,120 if exam=='oge' else 90,official=True)
speak('fipi-ege-questions','ege',2,'Cooking masterclass','You are considering going to a cooking masterclass. Ask four direct questions about the following points.',90,20,['kinds of dishes','number of people in the group','the duration of the masterclass','tuition fee'],True)
speak('fipi-ege-interview','ege',3,'Online shopping','Give full answers to the five interview questions (2–3 communicatively meaningful phrases per answer).',0,40,['Have you ever bought anything online?','Why do you think some people enjoy shopping online?','What are some of the disadvantages of shopping online?','Do you think it is a good idea to buy food online? Why or why not?','What would you recommend to a teenager who is going to buy some clothes online?'],True)
speak('fipi-oge-survey','oge',2,'Homework','Answer the six questions of the telephone survey.',0,40,['How many lessons do you usually have?','What do you usually do after lessons?','How much time do you need to do your homework?','Who helps you to do your homework?','Do you use the Internet when you do your homework? What for?','What would you recommend to a student who wants to spend less time on his or her homework?'],True)
speak('fipi-oge-monologue','oge',3,'Your school','Give a connected talk about your school (10–12 phrases).',90,120,['what your typical school day is like','what your favourite subject is, and why','what you like most about your school','what your attitude to your school life is'],True)
read_auth='Urban gardens are becoming common in many cities. People grow vegetables on roofs, balconies and small pieces of unused land. These gardens can provide fresh food, but their value is not limited to the harvest. Neighbours who rarely spoke before begin to work together. Children discover how plants develop and why water matters. Some gardens also collect rainwater and create safe places for insects. Starting a garden requires careful planning. People need to check the quality of the soil, find suitable plants and agree on a watering schedule. Not every attempt succeeds immediately, especially when the weather is unusual. However, sharing the work helps the group solve problems. Even a small garden can change the way people feel about the place where they live.'
for exam in ['oge','ege']:
    speak('author-'+exam+'-read',exam,1,'Urban gardens',read_auth,90,120 if exam=='oge' else 90)
for title,qs in [('Free time',['What do you usually do after school?','What hobby would you like to try, and why?','How do your friends spend their free time?','Why is it important to have time to relax?','What would you recommend to someone looking for a new hobby?','Do you prefer indoor or outdoor activities, and why?']),('The environment',['What do you do to save energy at home?','How can schools reduce waste?','Why do some people prefer public transport?','What environmental problem concerns you most?','What would you recommend to someone who wants to help their town?','Do you think young people can make a difference, and why?'])]:
    for exam in ['oge','ege']: speak('author-'+exam+'-'+title.lower().replace(' ','-'),exam,2 if exam=='oge' else 3,title,'Answer each question fully. Keep to the question and explain your ideas.',0,40,qs if exam=='oge' else qs[:5])
speak('author-ege-club','ege',2,'A new language club','Ask four direct questions about the new language club.',90,20,['start date','location','price of one lesson','group size'])
for topic,aspects in [('Reading',['why people read books','what kinds of books you enjoy','where you prefer reading','what your attitude to reading is']),('Healthy habits',['what people can do to stay healthy','what physical activity you enjoy and why','how your school encourages healthy habits','what your attitude to a healthy lifestyle is'])]:
    speak('author-oge-'+topic.lower().replace(' ','-'),'oge',3,topic,'Give a connected talk (10–12 phrases). Cover all four points.',90,120,aspects)
speak('author-ege-project','ege',4,'Learning alone or together','You and your friend are doing a project “Learning alone or together”. Leave a voice message explaining your choice of illustrations and sharing ideas (12–15 phrases). The illustrations below are educational drawings, not exam photographs.',150,180,['explain your choice of illustrations by briefly describing them and noting differences','mention 1–2 advantages of both ways of learning','mention 1–2 disadvantages of both ways of learning','say which way of learning you prefer and explain why'],images=['assets/learning-alone.svg','assets/learning-together.svg'])

for exam in ['oge','ege']:
    for i,(subject,qs,ask) in enumerate([
        ('School clubs',['What school club would you like to join?','What activities do you enjoy doing with friends?','Do you prefer learning something new alone or in a group, and why?'],'the new drama club'),
        ('Weekend plans',['Where do you usually go at weekends?','What do you like doing outdoors?','Would you prefer a quiet weekend or an active one, and why?'],'the upcoming school trip'),
        ('Books and films',['What kind of stories do you enjoy?','Do you prefer books or films, and why?','How do you choose what to read next?'],'the book festival')]):
        out['writing'].append(dict(id=f'author-{exam}-email-{i}',exam=exam,task=35 if exam=='oge' else 37,title=subject,text='From: Alex\nSubject: '+subject+'\n\n…'+ ' '.join(qs)+'\n\nWrite an email to Alex. Answer the three questions.'+(' Ask three questions about '+ask+'.' if exam=='ege' else ''),rubric=f'{exam}-writing-'+('35' if exam=='oge' else '37'),source=source(exam)))
out['writing'].append(dict(id='author-ege-38-reading',exam='ege',task=38,title='Choosing books',text='Imagine that you are doing a project on what helps teenagers in Zetland choose a book. You have found a survey (see table). Comment on the data and give your opinion. Write 200–250 words.\n\nMake an opening statement on the subject. Select and report 2–3 facts. Make 1–2 comparisons and give your comments. Outline a problem that can arise when choosing a book and suggest a solution. Conclude by giving and explaining your opinion on the importance of reading for teenagers.',table=[['Friends’ recommendations','35%'],['Online reviews','25%'],['The author’s name','20%'],['The cover','12%'],['The price','8%']],rubric='ege-writing-38',source=source('ege')))

(ROOT/'content.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(f"{len(out['items'])} sets, {sum(len(i.get('questions',[])) or len(i.get('key','')) for i in out['items'])} answer positions, {len(out['speaking'])} speaking tasks, {len(out['writing'])} writing tasks")
